import base64
import json
from pathlib import Path

from .cosmoscli import CosmosCLI
from .utils import find_log_event_attrs

V9_PLAN = "v9"
# Generated by app.TestMLDSAClientFixtures: a 07-tendermint client trusted at
# height 1-1 and a header at 1-2 signed by two ML-DSA-65 validators.
MLDSA_FIXTURES = Path(__file__).parent / "data/mldsa65"
RELAYER = "community"


def _cli(cluster, cmd=None):
    cli = cluster.cosmos_cli()
    if cmd is None:
        return cli
    return CosmosCLI(cli.data_dir, cli.node_rpc, chain_id=cli.chain_id, cmd=cmd)


def _ibc_client_tx(cli, *args):
    rsp = json.loads(
        cli.raw(
            "tx",
            "ibc",
            "client",
            *args,
            "-y",
            from_=RELAYER,
            home=cli.data_dir,
            node=cli.node_rpc,
            keyring_backend="test",
            chain_id=cli.chain_id,
            output="json",
            gas=2000000,
        )
    )
    if rsp["code"] == 0:
        rsp = cli.event_query_tx_for(rsp["txhash"])
    return rsp


def _update_mldsa_client(cli, client_id, tmp_path, tamper=False):
    header = json.loads((MLDSA_FIXTURES / "header.json").read_text())
    if tamper:
        sig_holder = header["signed_header"]["commit"]["signatures"][0]
        sig = bytearray(base64.b64decode(sig_holder["signature"]))
        sig[0] ^= 0xFF
        sig_holder["signature"] = base64.b64encode(sig).decode()
    path = tmp_path / ("header_tampered.json" if tamper else "header.json")
    path.write_text(json.dumps(header))
    return _ibc_client_tx(cli, "update", client_id, str(path))


def _consensus_heights(cli, client_id):
    rsp = json.loads(
        cli.raw(
            "query",
            "ibc",
            "client",
            "consensus-state-heights",
            client_id,
            node=cli.node_rpc,
            output="json",
        )
    )
    return [int(h["revision_height"]) for h in rsp["consensus_state_heights"]]


def setup_pre_v9_upgrade(cluster, tmp_path):
    """On the v8 binary (CometBFT v0.38.22), create a client of an ML-DSA-65
    counterparty and show its header update is rejected. The v9 binary signs
    the update, since the v8 CLI cannot parse an ML-DSA-65 key either.
    """
    cli = _cli(cluster)
    rsp = _ibc_client_tx(
        cli,
        "create",
        str(MLDSA_FIXTURES / "client_state.json"),
        str(MLDSA_FIXTURES / "consensus_state.json"),
    )
    assert rsp["code"] == 0, rsp["raw_log"]
    client_id = find_log_event_attrs(rsp["events"], "create_client")["client_id"]

    v9_cmd = cluster.data_root / f"cosmovisor/upgrades/{V9_PLAN}/bin/chain-maind"
    rsp = _update_mldsa_client(_cli(cluster, v9_cmd), client_id, tmp_path)
    # v0.38.22 has no PublicKey.mldsa65 field, so the tx fails to decode.
    assert rsp["code"] != 0, f"v8 must reject an ML-DSA-65 header, got {rsp}"
    assert 'errUnknownField "*crypto.PublicKey": {TagNum: 4' in rsp["raw_log"], rsp
    assert "tx parse error" in rsp["raw_log"], rsp["raw_log"]
    assert _consensus_heights(cli, client_id) == [1]
    return {"client_id": client_id}


def assert_v9_mldsa_client_update(cluster, ctx, tmp_path):
    """On the v9 binary, the same client rejects a tampered ML-DSA-65
    signature and accepts the valid header from before the upgrade."""
    cli = _cli(cluster)
    client_id = ctx["client_id"]

    rsp = _update_mldsa_client(cli, client_id, tmp_path, tamper=True)
    assert rsp["code"] != 0, f"tampered ML-DSA-65 header must fail, got {rsp}"
    assert "wrong signature" in rsp["raw_log"], rsp["raw_log"]

    rsp = _update_mldsa_client(cli, client_id, tmp_path)
    assert rsp["code"] == 0, rsp["raw_log"]
    assert _consensus_heights(cli, client_id) == [1, 2]
